-- Create a custom type for the job status so PostgreSQL enforces valid values.
CREATE TYPE job_status AS ENUM (
    'queued',
    'running',
    'completed',
    'failed',
    'dead_lettered'
);

-- Main jobs table. Every background job is stored here from creation
-- through completion or dead-lettering.
CREATE TABLE jobs (
    -- UUID primary key generated by the application
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    -- What kind of job this is (e.g. "send_email", "process_file")
    job_type        TEXT NOT NULL,

    -- Arbitrary JSON data the handler needs to do its work
    payload         JSONB NOT NULL DEFAULT '{}',

    -- Current lifecycle state
    status          job_status NOT NULL DEFAULT 'queued',

    -- How many times this job has been attempted so far
    attempts        INTEGER NOT NULL DEFAULT 0,

    -- Maximum number of attempts before the job is dead-lettered
    max_attempts    INTEGER NOT NULL DEFAULT 3,

    -- Earliest time the job may be picked up (supports delayed jobs)
    run_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    -- Set when a worker claims the job to prevent double-processing
    locked_at       TIMESTAMPTZ,
    locked_by       TEXT,

    -- The error message from the most recent failed attempt
    last_error      TEXT,

    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    completed_at    TIMESTAMPTZ
);

-- Index for the worker's polling query: find queued jobs ready to run
CREATE INDEX idx_jobs_status_run_at ON jobs (status, run_at)
    WHERE status = 'queued';

-- Index for looking up jobs by status (used by the API)
CREATE INDEX idx_jobs_status ON jobs (status);

-- Automatically update updated_at whenever a row changes
CREATE OR REPLACE FUNCTION touch_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER jobs_updated_at
    BEFORE UPDATE ON jobs
    FOR EACH ROW
    EXECUTE FUNCTION touch_updated_at();
